#include <Cellerator/compiler/profile/implement_streaming_profile_builders_v1.hh>
#include <cassert>
int main(){using namespace cellerator::compiler::profile::v1;std::uint64_t hist[8],sketch[16];double top[4],exact[4];streaming_profile_policy_v1 p{sizeof(hist)+sizeof(sketch)+sizeof(top)+sizeof(exact),8,4,16,true};streaming_profile_builder_v1 b{};assert(initialize_streaming_profile_builder_v1(p,{hist,top,sketch,exact,p.memory_budget_bytes},&b)==streaming_profile_status_v1::ok);double v[]={1,2,3,4};assert(update_streaming_profile_builder_v1(&b,v,4)==streaming_profile_status_v1::ok);streaming_profile_result_v1 r{};assert(finalize_streaming_profile_builder_v1(b,&r)==streaming_profile_status_v1::ok);assert(r.count==4&&r.mean==2.5&&r.variance==1.25&&top[0]==4);std::uint32_t counts[]={2,0,3};std::uint64_t offsets[4],total;assert(count_scan_fill_offsets_v1(counts,3,offsets,4,&total)==streaming_profile_status_v1::ok);assert(offsets[2]==2&&total==5);p.memory_budget_bytes--;assert(initialize_streaming_profile_builder_v1(p,{hist,top,sketch,exact,sizeof(hist)+sizeof(sketch)+sizeof(top)+sizeof(exact)},&b)==streaming_profile_status_v1::insufficient_budget);}
